package com.basilisk.two;
import android.app.Activity; import android.os.Bundle; import android.content.SharedPreferences; import android.widget.Button; import android.widget.EditText; import android.widget.TextView;
public final class MainActivity extends Activity { private EditText note; private TextView status; private SharedPreferences preferences; @Override public void onCreate(Bundle state) { super.onCreate(state); setContentView(R.layout.activity_main); note=findViewById(R.id.note); status=findViewById(R.id.status); preferences=getSharedPreferences("basilisk2",MODE_PRIVATE); note.setText(preferences.getString("note","")); status.setText("Notes stay on this device."); Button save=findViewById(R.id.save); save.setOnClickListener(v->{preferences.edit().putString("note",note.getText().toString()).apply();status.setText("Saved locally.");}); }}
